import { Book, BookStatus } from './types';

function computeBookFields(book: Omit<Book, 'available' | 'status'>): Book {
  const available = book.inventory - book.reserved;
  let status: BookStatus;
  if (book.arrival_date && new Date(book.arrival_date) > new Date()) {
    status = 'Pre-order';
  } else if (available > 0) {
    status = 'On Hand';
  } else {
    status = 'Sold Out';
  }
  return { ...book, available, status };
}

